import { describe, expect, it } from 'vitest';
import vectors from './shipping-quotes-v1.vectors.json';
import {
  legacyShippingOption,
  quoteAllShippingRates,
  quoteShipping,
  shippedCountries,
  type ShippingQuote,
  type ShippingQuoteErrorCode,
  type ShippingZone,
  shippingZonesSchema,
} from './shipping-zones';

// The vectors are generated by `src/test_fixtures/gen_shipping_quotes.py` in
// pubky/pubky-market-specs from the pricing rules in its SPEC.md; the Rust
// quote function is tested against the same file. A change to the vectors is
// a change to the spec, so this file is vendored byte for byte.

type ZoneSetName = keyof typeof vectors.zoneSets;
type Expected = ShippingQuote | { error: ShippingQuoteErrorCode };

function zonesOf(name: ZoneSetName): ShippingZone[] {
  return shippingZonesSchema.parse(vectors.zoneSets[name].zones);
}

describe('shipping quote vectors', () => {
  it.each(vectors.quotes.map((vector, index) => [index, vector] as const))('quote vector %i', (_index, vector) => {
    const set = vectors.zoneSets[vector.zones as ZoneSetName];
    const result = quoteShipping(
      zonesOf(vector.zones as ZoneSetName),
      set.excludedCountries,
      vector.destination,
      vector.rateId,
      vector.units,
    );
    const expected = vector.expected as Expected;
    if ('error' in expected) {
      expect(result).toEqual({ ok: false, code: expected.error });
    } else {
      expect(result).toEqual({ ok: true, value: expected });
    }
  });

  it.each(vectors.allRates.map((vector, index) => [index, vector] as const))(
    'all-rates vector %i',
    (_index, vector) => {
      const set = vectors.zoneSets[vector.zones as ZoneSetName];
      const result = quoteAllShippingRates(
        zonesOf(vector.zones as ZoneSetName),
        set.excludedCountries,
        vector.destination,
        vector.units,
      );
      const expected = vector.expected as { quotes: ShippingQuote[] } | { error: ShippingQuoteErrorCode };
      if ('error' in expected) {
        expect(result).toEqual({ ok: false, code: expected.error });
      } else {
        expect(result).toEqual({ ok: true, value: expected.quotes });
      }
    },
  );

  it.each(vectors.legacy.map((vector, index) => [index, vector] as const))(
    'legacy option vector %i',
    (_index, vector) => {
      const zones = shippingZonesSchema.parse(vector.zones);
      expect(
        legacyShippingOption(zones, { currency: vectors.currency, exponent: vectors.exponent }, 'legacy', 'Shipping'),
      ).toEqual(vector.expected);
    },
  );

  it('covers every refusal code the service answers with', () => {
    const codes = new Set(
      vectors.quotes.flatMap((vector) => ('error' in vector.expected ? [vector.expected.error] : [])),
    );
    expect([...codes].sort()).toEqual([
      'INVALID_DESTINATION',
      'INVALID_QUANTITY',
      'SHIPPING_OVERFLOW',
      'SHIPPING_UNAVAILABLE_TO_COUNTRY',
      'UNKNOWN_SHIPPING_RATE',
    ]);
  });
});

describe('zone validation', () => {
  const rate = {
    pricing: 'flat',
    rateId: 'std',
    label: 'Standard',
    amountMinor: 500,
    estimatedMinDays: 2,
    estimatedMaxDays: 5,
  };
  const zone = (zoneId: string, countries: string[], extra: Record<string, unknown> = {}) => ({
    zoneId,
    name: zoneId,
    countries,
    rates: [rate],
    ...extra,
  });

  it('accepts a zone list that lets an explicit country beat rest of world', () => {
    const zones = shippingZonesSchema.parse([zone('us', ['US']), zone('row', [], { restOfWorld: true })]);
    const quote = quoteShipping(zones, [], 'US', 'std', 3);
    expect(quote).toMatchObject({ ok: true, value: { zoneId: 'us', amountMinor: 500 } });
    expect(quoteShipping(zones, [], 'JP', 'std', 1)).toMatchObject({ ok: true, value: { zoneId: 'row' } });
  });

  it('refuses a country in two zones, two rest-of-world zones, and a zone that serves nobody', () => {
    expect(shippingZonesSchema.safeParse([zone('a', ['US']), zone('b', ['US'])]).success).toBe(false);
    expect(
      shippingZonesSchema.safeParse([zone('a', [], { restOfWorld: true }), zone('b', [], { restOfWorld: true })])
        .success,
    ).toBe(false);
    expect(shippingZonesSchema.safeParse([zone('a', [])]).success).toBe(false);
    expect(shippingZonesSchema.safeParse([zone('a', ['US']), zone('a', ['DE'])]).success).toBe(false);
  });

  it('refuses a rate the reader cannot price and an estimate that runs backwards', () => {
    expect(
      shippingZonesSchema.safeParse([zone('a', ['US'], { rates: [{ ...rate, pricing: 'calculated' }] })]).success,
    ).toBe(false);
    expect(
      shippingZonesSchema.safeParse([
        zone('a', ['US'], { rates: [{ ...rate, estimatedMinDays: 9, estimatedMaxDays: 3 }] }),
      ]).success,
    ).toBe(false);
    expect(shippingZonesSchema.safeParse([zone('a', ['US'], { rates: [{ ...rate, amountMinor: -1 }] })]).success).toBe(
      false,
    );
  });

  it('lists the countries a profile ships to, or none when it covers the rest of the world', () => {
    const zones = shippingZonesSchema.parse([zone('eu', ['DE', 'PT']), zone('us', ['US'])]);
    expect(shippedCountries(zones, ['PT'])).toEqual(['DE', 'US']);
    expect(shippedCountries(shippingZonesSchema.parse([zone('row', [], { restOfWorld: true })]), [])).toBeNull();
  });
});
